import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.scss']
})
export class LoginComponent {
  loginForm: FormGroup;
  errorMessage = '';
  successMessage = '';
  isLoading = false;
  showForgotPassword = false;
  forgotEmail = '';
  resetToken = '';
  newPassword = '';
  resetStep: 'request' | 'reset' = 'request';

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private router: Router
  ) {
    this.loginForm = this.fb.group({
      email: ['', [Validators.required, Validators.email]],
      password: ['', Validators.required]
    });
  }

  onSubmit(): void {
    if (this.loginForm.valid) {
      this.isLoading = true;
      this.errorMessage = '';
      const { email, password } = this.loginForm.value;
      this.authService.login(email, password).subscribe({
        next: () => {
          this.isLoading = false;
          this.router.navigate(['/dashboard']);
        },
        error: (err) => {
          this.isLoading = false;
          this.errorMessage = err.error?.message || 'Email ou mot de passe incorrect';
        }
      });
    }
  }

  openForgotPassword(): void {
    this.showForgotPassword = true;
    this.resetStep = 'request';
    this.forgotEmail = '';
    this.errorMessage = '';
    this.successMessage = '';
  }

  closeForgotPassword(): void {
    this.showForgotPassword = false;
    this.resetStep = 'request';
    this.forgotEmail = '';
    this.resetToken = '';
    this.newPassword = '';
    this.errorMessage = '';
    this.successMessage = '';
  }

  onForgotSubmit(): void {
    if (!this.forgotEmail) {
      this.errorMessage = 'Veuillez saisir votre email';
      return;
    }
    this.isLoading = true;
    this.errorMessage = '';
    this.successMessage = '';

    this.authService.forgotPassword(this.forgotEmail).subscribe({
      next: (response) => {
        this.isLoading = false;
        if (response.success) {
          this.successMessage = response.message;
          this.resetStep = 'reset';
        } else {
          this.errorMessage = response.message || 'Erreur';
        }
      },
      error: (err) => {
        this.isLoading = false;
        this.errorMessage = err.error?.message || 'Erreur lors de la demande';
      }
    });
  }

  onResetSubmit(): void {
    if (!this.resetToken || !this.newPassword || this.newPassword.length < 6) {
      this.errorMessage = 'Le token et le mot de passe (6 caractères min) sont requis';
      return;
    }
    this.isLoading = true;
    this.errorMessage = '';
    this.successMessage = '';

    this.authService.resetPassword(this.forgotEmail, this.resetToken, this.newPassword).subscribe({
      next: (response) => {
        this.isLoading = false;
        if (response.success) {
          this.successMessage = response.message;
          setTimeout(() => {
            this.closeForgotPassword();
          }, 3000);
        } else {
          this.errorMessage = response.message || 'Erreur';
        }
      },
      error: (err) => {
        this.isLoading = false;
        this.errorMessage = err.error?.message || 'Erreur lors de la réinitialisation';
      }
    });
  }

  goToRegister(): void {
    this.router.navigate(['/inscription']);
  }
}
<div class="login-page">
  <div class="login-container">
    <div class="login-card">
      <div class="login-header">
        <h2>🔐 Ministère App</h2>
        <p>{{ showForgotPassword ? 'Réinitialisation du mot de passe' : 'Connexion sécurisée' }}</p>
      </div>

      <!-- Formulaire de connexion -->
      <form *ngIf="!showForgotPassword" [formGroup]="loginForm" (ngSubmit)="onSubmit()">
        <div class="form-group">
          <label>📧 Email</label>
          <input type="email" formControlName="email" placeholder="email@exemple.com" class="form-control">
        </div>
        <div class="form-group">
          <label>🔒 Mot de passe</label>
          <input type="password" formControlName="password" placeholder="Votre mot de passe" class="form-control">
        </div>

        <div class="form-options">
          <a (click)="openForgotPassword()" class="forgot-link">Mot de passe oublié ?</a>
        </div>

        <button type="submit" class="btn btn-primary btn-block" [disabled]="loginForm.invalid || isLoading">
          {{ isLoading ? '⏳ Connexion...' : 'Se connecter' }}
        </button>

        <div *ngIf="errorMessage" class="alert alert-danger">{{ errorMessage }}</div>

        <p class="register-link">
          Pas encore de compte ? <span class="btn-link" (click)="goToRegister()">S'inscrire</span>
        </p>
      </form>

      <!-- Formulaire mot de passe oublié -->
      <div *ngIf="showForgotPassword">
        <div *ngIf="resetStep === 'request'">
          <p>Saisissez votre email pour recevoir un lien de réinitialisation.</p>
          <div class="form-group">
            <label>Email</label>
            <input type="email" [(ngModel)]="forgotEmail" placeholder="email@exemple.com" class="form-control">
          </div>
          <button class="btn btn-primary" (click)="onForgotSubmit()" [disabled]="isLoading">
            {{ isLoading ? '⏳ Envoi...' : 'Envoyer le lien' }}
          </button>
          <button class="btn btn-secondary" (click)="closeForgotPassword()">Annuler</button>
        </div>

        <div *ngIf="resetStep === 'reset'">
          <p>Un token a été généré. Saisissez-le avec votre nouveau mot de passe.</p>
          <div class="form-group">
            <label>Token</label>
            <input type="text" [(ngModel)]="resetToken" placeholder="Token reçu" class="form-control">
          </div>
          <div class="form-group">
            <label>Nouveau mot de passe (6 caractères min)</label>
            <input type="password" [(ngModel)]="newPassword" placeholder="Nouveau mot de passe" class="form-control">
          </div>
          <button class="btn btn-primary" (click)="onResetSubmit()" [disabled]="isLoading">
            {{ isLoading ? '⏳ Réinitialisation...' : 'Réinitialiser' }}
          </button>
          <button class="btn btn-secondary" (click)="closeForgotPassword()">Annuler</button>
        </div>

        <div *ngIf="successMessage" class="alert alert-success">{{ successMessage }}</div>
        <div *ngIf="errorMessage" class="alert alert-danger">{{ errorMessage }}</div>
      </div>
    </div>
  </div>
</div>
